import { CommonModule } from '@angular/common';
import { Component, Input } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'factbox',
  standalone: true,
  imports: [MatCheckboxModule, FormsModule, CommonModule, TranslateModule],
  templateUrl: './factbox.component.html',
  styleUrl: './factbox.component.scss'
})
export class FactboxComponent {
  @Input() inTable: boolean = false;
  @Input() mode: string = 'dark';
  @Input() jTexts: string[] = [];
  @Input() classList: string = '';
  @Input() jOT: string[] = [];
  @Input() bIsHighlighted: boolean = false;
  @Input() isLarge: boolean = false;
  @Input() ishilight: boolean = false;
}
